package com.printflow;
import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;import java.io.*;
import org.junit.jupiter.api.*;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.test.annotation.DirtiesContext;import tools.jackson.databind.json.JsonMapper;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"server.address=127.0.0.1","app.staff.bootstrap.enabled=false","app.owner.bootstrap.enabled=false","APP_MAIL_ENABLED=false","app.demo.enabled=false","server.servlet.session.cookie.secure=false"})
@TestInstance(TestInstance.Lifecycle.PER_CLASS) @DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
class LiveWorkIntegrationTest {
 @LocalServerPort int port;@Autowired JdbcTemplate jdbc;@Autowired PasswordEncoder passwords;@Autowired JsonMapper json;
 UUID sales=UUID.randomUUID(),customer=UUID.randomUUID(),stranger=UUID.randomUUID(),designer=UUID.randomUUID();String password=UUID.randomUUID().toString();Client seller,buyer,other,artist;
 @BeforeAll void setup()throws Exception{for(var row:List.of(new Object[]{sales,"SALES"},new Object[]{customer,"CUSTOMER"},new Object[]{stranger,"CUSTOMER"},new Object[]{designer,"DESIGNER"}))jdbc.update("insert into staff_users(id,username,password_hash,role,public_name) values(?,?,?,?,?)",row[0],"it-live-"+row[0]+"@example.test",passwords.encode(password),row[1],"Studio team");seller=login(sales);buyer=login(customer);other=login(stranger);artist=login(designer);}
 @AfterAll void cleanup(){for(UUID id:List.of(sales,customer,stranger,designer))jdbc.update("update staff_users set enabled=false,avatar_png=null where id=?",id);}
 Client login(UUID id)throws Exception{var c=new Client();assertEquals(200,c.login("it-live-"+id+"@example.test",password));return c;}
 UUID lead(){UUID id=UUID.randomUUID();jdbc.update("insert into enquiries(id,public_id,tracking_token_sha256,customer_name,email,phone,product_code,quantity,status,assigned_staff_id,customer_user_id,designer_id,requested_date) values(?,?,?,'Synthetic live customer','live@example.test','9000000000','WEDDING_CARDS',250,'REVIEWING',?,?,?,?)",id,UUID.randomUUID(),"0".repeat(64),sales,customer,designer,LocalDate.now(ZoneId.of("Asia/Kolkata")).plusDays(5));return id;}
 String path(UUID id){return "/api/v1/staff/enquiries/"+id+"/quotes";}String work(UUID id){return "/api/v1/design/enquiries/"+id+"/work";}
 Map<String,Object> data(HttpResponse<String> r){return json.readValue(r.body(),Map.class);}
 String issue(boolean offline,String evidence){var m=new HashMap<String,Object>();m.put("expectedVersion",0);m.put("scope","250 invitations and envelopes");m.put("totalPaise",125050);m.put("terms","All-inclusive. Collection arranged separately.");m.put("proposedDate",LocalDate.now(ZoneId.of("Asia/Kolkata")).plusDays(7).toString());m.put("acceptedOffline",offline);if(offline){m.put("acceptanceSource","PHONE");m.put("acceptanceEvidence",evidence);}return json.writeValueAsString(m);}
 @Test void quotationDrivesStatusAndIsoDates()throws Exception{UUID id=lead();assertEquals(409,seller.send("PATCH","/api/v1/staff/enquiries/"+id+"/status","{\"revision\":0,\"status\":\"QUOTED\"}",true).statusCode());var r=seller.send("POST",path(id),issue(false,""),true);assertEquals(201,r.statusCode(),r.body());var q=data(r);assertTrue(q.get("proposed_date") instanceof String);assertTrue(q.get("proposed_date").toString().matches("\\d{4}-\\d{2}-\\d{2}"));assertNotNull(q.get("requested_date"));assertFalse(q.containsKey("valid_until"));assertEquals("QUOTED",jdbc.queryForObject("select status from enquiries where id=?",String.class,id));var response=buyer.send("POST","/api/v1/customer/enquiries/"+id+"/quotes/"+q.get("id")+"/decision","{\"action\":\"ACCEPT\",\"note\":\"\"}",true);assertEquals(200,response.statusCode(),response.body());assertEquals("IN_PROGRESS",jdbc.queryForObject("select status from enquiries where id=?",String.class,id));assertTrue((Boolean)data(buyer.send("GET",work(id),null,false)).get("liveWork"));}
 @Test void offlineAcceptanceNeedsEvidenceAndIsNotCustomerImpersonation()throws Exception{UUID id=lead();assertEquals(400,seller.send("POST",path(id),issue(true,"ok"),true).statusCode());var r=seller.send("POST",path(id),issue(true,"Customer confirmed all terms during the synthetic phone discussion."),true);assertEquals(201,r.statusCode(),r.body());assertEquals("PHONE",data(r).get("acceptance_source"));assertEquals("ACCEPTED",data(r).get("state"));assertEquals(sales,jdbc.queryForObject("select acceptance_recorded_by from quote_versions where enquiry_id=?",UUID.class,id));assertTrue(buyer.send("GET","/api/v1/customer/enquiries",null,false).body().contains("\"live_work\":true"));assertThrows(org.springframework.dao.DataAccessException.class,()->jdbc.update("update quote_versions set acceptance_evidence='changed' where enquiry_id=?",id));}
 @Test void sharedConversationAndScope()throws Exception{UUID id=lead();assertEquals(201,seller.send("POST",path(id),issue(true,"Customer agreed the full quotation by phone at the synthetic test time."),true).statusCode());assertEquals(404,other.send("GET",work(id),null,false).statusCode());assertEquals(403,buyer.send("POST",work(id)+"/messages","{\"body\":\"Hello\"}",false).statusCode());assertEquals(200,buyer.send("POST",work(id)+"/messages","{\"body\":\"Please review the invitation spelling\"}",true).statusCode());assertEquals(200,artist.send("POST",work(id)+"/messages","{\"body\":\"Designer will review this\"}",true).statusCode());var view=data(buyer.send("GET",work(id),null,false));assertEquals("Studio team",view.get("designer"));assertEquals(false,view.get("mailConnected"));assertEquals("Not released",((Map<?,?>)view.get("stages")).get("production"));assertFalse(json.writeValueAsString(view).contains("password"));assertFalse(json.writeValueAsString(view).contains("assigned_staff_id"));}
 @Test void reasonedRemovalPreservesHistoryAndSortsClosedLast()throws Exception{UUID first=lead(),second=lead();assertEquals(201,seller.send("POST",path(first),issue(true,"Customer confirmed acceptance over the synthetic phone call."),true).statusCode());long revision=jdbc.queryForObject("select revision from enquiries where id=?",Long.class,first);String route="/api/v1/staff/enquiries/"+first+"/resolve";assertEquals(400,seller.send("POST",route,json.writeValueAsString(Map.of("revision",revision,"kind","REJECTED","message","bad")),true).statusCode());assertEquals(200,seller.send("POST",route,json.writeValueAsString(Map.of("revision",revision,"kind","REJECTED","message","Customer asked to cancel this print request after discussing the revised plans.")),true).statusCode());assertEquals(1,jdbc.queryForObject("select count(*) from quote_versions where enquiry_id=?",Integer.class,first));assertTrue(buyer.send("GET","/api/v1/customer/enquiries/"+first,null,false).body().contains("Customer asked to cancel"));List<?> rows=json.readValue(buyer.send("GET","/api/v1/customer/enquiries",null,false).body(),List.class);int open=-1,closed=-1;for(int i=0;i<rows.size();i++){var m=(Map<?,?>)rows.get(i);if(second.toString().equals(m.get("id")))open=i;if(first.toString().equals(m.get("id")))closed=i;}assertTrue(open>=0&&closed>open);assertEquals(409,buyer.send("POST",work(first)+"/messages","{\"body\":\"Closed message\"}",true).statusCode());}
 @Test void privateReencodedProfilePhotos()throws Exception{var image=new java.awt.image.BufferedImage(32,32,java.awt.image.BufferedImage.TYPE_INT_RGB);var out=new ByteArrayOutputStream();javax.imageio.ImageIO.write(image,"PNG",out);assertEquals(200,buyer.send("POST","/api/v1/auth/appearance/image",json.writeValueAsString(Map.of("base64",Base64.getEncoder().encodeToString(out.toByteArray()))),true).statusCode());assertEquals(true,data(buyer.send("GET","/api/v1/auth/appearance",null,false)).get("has_image"));assertEquals(false,data(other.send("GET","/api/v1/auth/appearance",null,false)).get("has_image"));assertEquals(400,buyer.send("POST","/api/v1/auth/appearance/image","{\"base64\":\"invalid\"}",true).statusCode());assertEquals(200,buyer.send("DELETE","/api/v1/auth/appearance/image",null,true).statusCode());assertEquals(false,data(buyer.send("GET","/api/v1/auth/appearance",null,false)).get("has_image"));}
    class Client {
        CookieManager cookies=new CookieManager(null,CookiePolicy.ACCEPT_ALL);
        HttpClient client=HttpClient.newBuilder().cookieHandler(cookies).build();
        String token;
        HttpResponse<String> send(String method,String path,String body,boolean csrf)throws Exception {
            var builder=HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+path)).timeout(Duration.ofSeconds(15));
            if(csrf){csrf();builder.header("X-CSRF-TOKEN",token);}
            if(body!=null)builder.header("Content-Type","application/json");
            return client.send(builder.method(method,body==null?HttpRequest.BodyPublishers.noBody():HttpRequest.BodyPublishers.ofString(body)).build(),HttpResponse.BodyHandlers.ofString());
        }
        void csrf()throws Exception {
            var response=send("GET","/api/v1/auth/csrf",null,false);
            assertEquals(200,response.statusCode());
            token=(String)json.readValue(response.body(),Map.class).get("token");
        }
        int login(String name,String secret)throws Exception {
            csrf();String before=cookies.getCookieStore().getCookies().stream().filter(c->c.getName().equals("JSESSIONID")).findFirst().orElseThrow().getValue();
            var response=client.send(HttpRequest.newBuilder(URI.create("http://127.0.0.1:"+port+"/api/v1/auth/session"))
                .header("Content-Type","application/x-www-form-urlencoded").header("X-CSRF-TOKEN",token)
                .POST(HttpRequest.BodyPublishers.ofString("username="+URLEncoder.encode(name,StandardCharsets.UTF_8)+"&password="+URLEncoder.encode(secret,StandardCharsets.UTF_8))).build(),HttpResponse.BodyHandlers.ofString());
            if(response.statusCode()==200){
                var cookie=cookies.getCookieStore().getCookies().stream().filter(c->c.getName().equals("JSESSIONID")).findFirst().orElseThrow();
                assertTrue(cookie.isHttpOnly());assertTrue(!before.equals(cookie.getValue()),"Login must rotate the session identifier");
            }
            return response.statusCode();
        }
    }

}
